package com.example.starter.incident;

/**
 * 资源状态：AVAILABLE 为来源事件自持可用；LEASED_OUT 为存在 ACTIVE 交接已跨事件借出。
 * 资源同一时刻至多受一条 ACTIVE 交接约束，故 LEASED_OUT 期间不可再次转借。
 */
public enum ResourceStatus {

    /** 来源事件自持，空闲可借。 */
    AVAILABLE,

    /** 已通过 ACTIVE 交接借出（含被目标事件已开始任务继续占用的超期时段）。 */
    LEASED_OUT;
}

package com.example.starter.incident;

/**
 * 跨事件互助交接状态：ACTIVE 为租约生效中（含已开始任务在租约到期后继续占用资源的情形）；
 * SETTLED 为已结算归还，终态。仅允许 ACTIVE→SETTLED，结算记录不可变。
 */
public enum HandoffStatus {

    /** 交接生效中：资源责任在目标事件侧。 */
    ACTIVE,

    /** 已结算：资源责任归还来源事件，终态。 */
    SETTLED;
}

package com.example.starter.incident;

/**
 * 交接结算触发原因（写入不可变 handoff_settlements，不再变更）：
 * TARGET_CLOSED 目标关闭时解除未开始任务并归还；LEASE_EXPIRED 租约到期显式结算；
 * TASK_DONE/TASK_CANCELLED 已开始任务到达终态后自动归还。
 */
public enum SettlementReason {

    /** 目标事件关闭：未开始任务解绑，资源归还来源。 */
    TARGET_CLOSED,

    /** 租约到期：未开始任务解绑，资源归还来源；已开始任务继续占用。 */
    LEASE_EXPIRED,

    /** 借用资源的已开始任务完成，任务终态自动归还。 */
    TASK_DONE,

    /** 借用资源的已开始任务取消，任务终态自动归还。 */
    TASK_CANCELLED;
}

