 * returnedResourceKey 为归还资源键，detail 记录解绑任务等明细。记录只追加，不更新不删除。
 * 时间均为 UTC。
 */
public record HandoffSettlement(
        long id,
        long handoffId,
        String reason,
        String returnedResourceKey,
        String detail,
        Instant settledAt,
        Instant createdAt) {
}

