        result.add(verifyReplay(concurrent, item, source, target, actor));
        continue;
    }
    resources.updateStatus(locked.id(), ResourceStatus.LEASED_OUT, now);
    result.add(handoffs.lockById(handoffId).orElseThrow());
}

