/**
 * 结算一条交接：存在已开始（STARTED）任务占用时不结算（资源继续被占用），返回空；
 * 否则解绑全部未开始（OPEN）任务，交接置 SETTLED、资源归还来源 AVAILABLE，
 * 写入一条不可变结算记录。调用方须持有目标事件行锁，交接行在此加锁防并发重复结算。
 */
private Optional<HandoffSettlementView> settleIfNoStartedTask(Handoff handoff,
                                                              SettlementReason reason,
                                                              Instant now) {
    Handoff locked = handoffs.lockById(handoff.id()).orElseThrow();
    if (locked.status() != HandoffStatus.ACTIVE) {
        return Optional.empty();
    }
    List<IncidentTask> started = tasks.listStartedByHandoff(locked.id());
    if (!started.isEmpty()) {
